from dspy.evaluate import normalize_text
from dspy.primitives.prediction import Completions, Prediction


def default_normalize(s):
    return normalize_text(s) or None


def majority(prediction_or_completions, normalize=default_normalize, field=None):
    """
    Returns the most common completion for the target field (or the last field) in the signature.
    When normalize returns None, that completion is ignored.
    In case of a tie, earlier completion are prioritized.
    """

    assert any(isinstance(prediction_or_completions, t) for t in [Prediction, Completions, list])
    type(prediction_or_completions)

    # Get the completions
    if isinstance(prediction_or_completions, Prediction):
        completions = prediction_or_completions.completions
    else:
        completions = prediction_or_completions

    try:
        signature = completions.signature
    except Exception:
        signature = None

    if not field:
        if signature:
            field = list(signature.output_fields.keys())[-1]
        else:
            field = list(completions[0].keys())[-1]

    # Normalize
    normalize = normalize if normalize else lambda x: x
    normalized_values = [normalize(completion[field]) for completion in completions]
    normalized_values_ = [x for x in normalized_values if x is not None]

    # Count
    value_counts = {}
    for value in normalized_values_ or normalized_values:
        value_counts[value] = value_counts.get(value, 0) + 1

    majority_value = max(value_counts, key=value_counts.get)

    # Return the first completion with the majority value in the field
    for completion in completions:
        if normalize(completion[field]) == majority_value:
            break

    # if input_type == Prediction:
    return Prediction.from_completions([completion], signature=signature)

from dspy.predict.predict import Predict
from dspy.primitives.module import Module
from dspy.signatures import InputField, OutputField
from dspy.signatures.signature import ensure_signature


class MultiChainComparison(Module):
    def __init__(self, signature, M=3, temperature=0.7, **config):  # noqa: N803
        super().__init__()

        self.M = M
        signature = ensure_signature(signature)

        *_, self.last_key = signature.output_fields.keys()

        for idx in range(M):
            signature = signature.append(
                f"reasoning_attempt_{idx+1}",
                InputField(
                    prefix=f"Student Attempt #{idx+1}:",
                    desc="${reasoning attempt}",
                ),
            )

        signature = signature.prepend(
            "rationale",
            OutputField(
                prefix="Accurate Reasoning: Thank you everyone. Let's now holistically",
                desc="${corrected reasoning}",
            ),
        )

        self.predict = Predict(signature, temperature=temperature, **config)

    def forward(self, completions, **kwargs):
        attempts = []

        for c in completions:
            rationale = c.get("rationale", c.get("reasoning")).strip().split("\n")[0].strip()
            answer = str(c[self.last_key]).strip().split("\n")[0].strip()
            attempts.append(
                f"«I'm trying to {rationale} I'm not sure but my prediction is {answer}»",
            )

        assert (
            len(attempts) == self.M
        ), f"The number of attempts ({len(attempts)}) doesn't match the expected number M ({self.M}). Please set the correct value for M when initializing MultiChainComparison."

        kwargs = {
            **{f"reasoning_attempt_{idx+1}": attempt for idx, attempt in enumerate(attempts)},
            **kwargs,
        }
        return self.predict(**kwargs)

"""
REPL data types for RLM and interpreter interactions.

These types represent the state and history of REPL-based execution:
- REPLVariable: Metadata about variables available in the REPL
- REPLEntry: A single interaction (reasoning, code, output)
- REPLHistory: Container for the full interaction history
"""

from __future__ import annotations

import json
from typing import TYPE_CHECKING, Any, Iterator

import pydantic
from pydantic import Field

from dspy.adapters.utils import serialize_for_json

if TYPE_CHECKING:
    from pydantic.fields import FieldInfo

__all__ = ["REPLVariable", "REPLEntry", "REPLHistory"]


class REPLVariable(pydantic.BaseModel):
    """Metadata about a variable available in the REPL environment."""

    name: str
    type_name: str
    desc: str = ""
    constraints: str = ""
    total_length: int
    preview: str

    model_config = pydantic.ConfigDict(frozen=True)

    @classmethod
    def from_value(
        cls,
        name: str,
        value: Any,
        field_info: FieldInfo | None = None,
        preview_chars: int = 1000,
    ) -> REPLVariable:
        """Create REPLVariable from an actual value and optional field info.

        Args:
            name: Variable name
            value: The actual value
            field_info: Optional pydantic FieldInfo with desc/constraints metadata
            preview_chars: Max characters for preview
        """
        jsonable = serialize_for_json(value)
        if isinstance(jsonable, (dict, list)):
            value_str = json.dumps(jsonable, indent=2)
        else:
            value_str = str(jsonable)
        is_truncated = len(value_str) > preview_chars
        if is_truncated:
            half = preview_chars // 2
            preview = value_str[:half] + "..." + value_str[-half:]
        else:
            preview = value_str

        # Extract desc and constraints from field_info if provided
        desc = ""
        constraints = ""
        if field_info and hasattr(field_info, "json_schema_extra") and field_info.json_schema_extra:
            raw_desc = field_info.json_schema_extra.get("desc", "")
            # Skip placeholder descs like "${name}"
            if raw_desc and not raw_desc.startswith("${"):
                desc = raw_desc
            constraints = field_info.json_schema_extra.get("constraints", "")

        return cls(
            name=name,
            type_name=type(value).__name__,
            desc=desc,
            constraints=constraints,
            total_length=len(value_str),
            preview=preview,
        )

    def format(self) -> str:
        """Format variable metadata for prompt inclusion."""
        lines = [f"Variable: `{self.name}` (access it in your code)"]
        lines.append(f"Type: {self.type_name}")
        if self.desc:
            lines.append(f"Description: {self.desc}")
        if self.constraints:
            lines.append(f"Constraints: {self.constraints}")
        lines.append(f"Total length: {self.total_length:,} characters")
        lines.append(f"Preview:\n```\n{self.preview}\n```")
        return "\n".join(lines)

    @pydantic.model_serializer()
    def serialize_model(self) -> str:
        return self.format()


class REPLEntry(pydantic.BaseModel):
    """A single REPL interaction entry containing reasoning, code, and output."""

    reasoning: str = ""
    code: str
    output: str

    model_config = pydantic.ConfigDict(frozen=True)

    @staticmethod
    def format_output(output: str, max_output_chars: int = 10_000) -> str:
        """Format output with head+tail truncation, preserving true length in header."""
        raw_len = len(output)
        if raw_len > max_output_chars:
            half = max_output_chars // 2
            omitted = raw_len - max_output_chars
            output = output[:half] + f"\n\n... ({omitted:,} characters omitted) ...\n\n" + output[-half:]
        return f"Output ({raw_len:,} chars):\n{output}"

    def format(self, index: int, max_output_chars: int = 10_000) -> str:
        """Format this entry for inclusion in prompts."""
        reasoning_line = f"Reasoning: {self.reasoning}\n" if self.reasoning else ""
        code_block = f"```python\n{self.code}\n```"
        return f"=== Step {index + 1} ===\n{reasoning_line}Code:\n{code_block}\n{self.format_output(self.output, max_output_chars)}"


class REPLHistory(pydantic.BaseModel):
    """Container for REPL interaction history.

    Immutable: append() returns a new instance with the entry added.
    """

    entries: list[REPLEntry] = Field(default_factory=list)
    max_output_chars: int = 10_000

    model_config = pydantic.ConfigDict(frozen=True)

    def format(self) -> str:
        if not self.entries:
            return "You have not interacted with the REPL environment yet."
        return "\n".join(entry.format(index=i, max_output_chars=self.max_output_chars) for i, entry in enumerate(self.entries))

    @pydantic.model_serializer()
    def serialize_model(self) -> str:
        return self.format()

    def append(self, *, reasoning: str = "", code: str, output: str) -> REPLHistory:
        """Return a new REPLHistory with the entry appended."""
        new_entry = REPLEntry(reasoning=reasoning, code=code, output=output)
        return REPLHistory(entries=list(self.entries) + [new_entry], max_output_chars=self.max_output_chars)

    def __len__(self) -> int:
        return len(self.entries)

    def __iter__(self) -> Iterator[REPLEntry]:
        return iter(self.entries)

    def __bool__(self) -> bool:
        return len(self.entries) > 0

    paths_to_mount = []
    if self.enable_read_paths:
        paths_to_mount.extend(self.enable_read_paths)
    if self.enable_write_paths:
        paths_to_mount.extend(self.enable_write_paths)
    if not paths_to_mount:
        return
    for path in paths_to_mount:
        if not path:
            continue
        if not os.path.exists(path):
            if self.enable_write_paths and path in self.enable_write_paths:
                open(path, "a").close()
            else:
                raise FileNotFoundError(f"Cannot mount non-existent file: {path}")
        virtual_path = f"/sandbox/{os.path.basename(path)}"
        self._send_request("mount_file", {"host_path": str(path), "virtual_path": virtual_path}, f"mounting {path}")
    self._mounted_files = True

def _sync_files(self):
    if not self.enable_write_paths or not self.sync_files:
        return
    for path in self.enable_write_paths:
        virtual_path = f"/sandbox/{os.path.basename(path)}"
        sync_msg = _jsonrpc_notification("sync_file", {"virtual_path": virtual_path, "host_path": str(path)})
        self.deno_process.stdin.write(sync_msg + "\n")
        self.deno_process.stdin.flush()

def _extract_parameters(self, fn: Callable) -> list[dict]:
    """Extract parameter info from a callable for sandbox registration."""
    sig = inspect.signature(fn)
    params = []
    for name, param in sig.parameters.items():
        p = {"name": name}
        # Only include type for simple types that work in function signatures
        # Complex types like Union, Optional, etc. are not included
        if param.annotation != inspect.Parameter.empty:
            if param.annotation in SIMPLE_TYPES:
                p["type"] = param.annotation.__name__
        if param.default != inspect.Parameter.empty:
            p["default"] = param.default
        params.append(p)
    return params

def _register_tools(self) -> None:
    """Register tools and output fields with the sandbox."""
    if self._tools_registered:
        return

    # Build registration params with typed tool signatures
    params = {}

    if self.tools:
        tools_info = []
        for name, fn in self.tools.items():
            tools_info.append({
                "name": name,
                "parameters": self._extract_parameters(fn)
            })
        params["tools"] = tools_info

    if self.output_fields:
        params["outputs"] = self.output_fields

    # Skip if nothing to register
    if not params:
        self._tools_registered = True
        return

    self._send_request("register", params, "registering tools/outputs")
    self._tools_registered = True

def _handle_tool_call(self, request: dict) -> None:
    """Handle a tool call request from the sandbox."""
    request_id = request["id"]
    params = request.get("params", {})
    tool_name = params.get("name")
    kwargs = params.get("kwargs", {})

    try:
        if tool_name not in self.tools:
            raise CodeInterpreterError(f"Unknown tool: {tool_name}")
        result = self.tools[tool_name](**kwargs)
        is_json = isinstance(result, (list, dict))
        response = _jsonrpc_result(
            {"value": json.dumps(result) if is_json else (str(result) if result is not None else ""), "type": "json" if is_json else "string"},
            request_id
        )
    except Exception as e:
        error_type = type(e).__name__
        error_code = JSONRPC_APP_ERRORS.get(error_type, JSONRPC_APP_ERRORS["Unknown"])
        response = _jsonrpc_error(error_code, str(e), request_id, {"type": error_type})

    self.deno_process.stdin.write(response + "\n")
    self.deno_process.stdin.flush()

def _ensure_deno_process(self) -> None:
    if self.deno_process is None or self.deno_process.poll() is not None:
        # Process identity changed (or process missing), so replay setup.
        self._tools_registered = False
        self._mounted_files = False
        try:
            self.deno_process = subprocess.Popen(
                self.deno_command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="UTF-8",
                env=os.environ.copy()
            )
        except FileNotFoundError as e:
            install_instructions = (
                "Deno executable not found. Please install Deno to proceed.\n"
                "Installation instructions:\n"
                "> curl -fsSL https://deno.land/install.sh | sh\n"
                "*or*, on macOS with Homebrew:\n"
                "> brew install deno\n"
                "For additional configurations: https://docs.deno.com/runtime/getting_started/installation/"
            )
            raise CodeInterpreterError(install_instructions) from e
        self._health_check()

_MAX_SKIP_LINES = 100

def _read_response_line(self, context: str) -> str:
    """Read one stdout line from Deno or raise a process-level error."""
    response_line = self.deno_process.stdout.readline().strip()
    if response_line:
        return response_line

    exit_code = self.deno_process.poll()
    if exit_code is not None:
        stderr = self.deno_process.stderr.read() if self.deno_process.stderr else ""
        raise CodeInterpreterError(f"Deno exited (code {exit_code}) {context}: {stderr}")
    raise CodeInterpreterError(f"No response {context}")

def _parse_response_line(self, response_line: str, context: str) -> dict | None:
    """Parse a JSON-RPC line, returning None for non-JSON or malformed lines."""
    if not response_line.startswith("{"):
        logger.debug("Skipping non-JSON output during %s: %s", context, response_line)
        return None

    try:
        return json.loads(response_line)
    except json.JSONDecodeError:
        logger.debug("Skipping malformed JSON during %s: %s", context, response_line[:100])
        return None

def _send_request(self, method: str, params: dict, context: str) -> dict:
    """Send a JSON-RPC request and return the parsed response.

    Non-JSON lines (e.g. Pyodide package loading messages) are skipped,
    up to ``_MAX_SKIP_LINES`` to prevent unbounded blocking.
    """
    self._request_id += 1
    request_id = self._request_id
    msg = _jsonrpc_request(method, params, request_id)
    self.deno_process.stdin.write(msg + "\n")
    self.deno_process.stdin.flush()

    skipped = 0
    while skipped <= self._MAX_SKIP_LINES:
        response_line = self._read_response_line(context)
        response = self._parse_response_line(response_line, context)
        if response is None:
            skipped += 1
            continue

        if response.get("id") != request_id:
            raise CodeInterpreterError(f"Response ID mismatch {context}: expected {request_id}, got {response.get('id')}")
        if "error" in response:
            raise CodeInterpreterError(f"Error {context}: {response['error'].get('message', 'Unknown error')}")
        return response

    raise CodeInterpreterError(f"Too many non-JSON lines ({skipped}) {context}")

def _health_check(self) -> None:
    """Verify the subprocess is alive by executing a simple expression."""
    response = self._send_request("execute", {"code": "print(1+1)"}, "during health check")
    if response.get("result", {}).get("output", "").strip() != "2":
        raise CodeInterpreterError(f"Unexpected ping response: {response}")

def _to_json_compatible(self, value: Any) -> Any:
    """Recursively convert Python values to JSON-compatible types."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    elif isinstance(value, dict):
        return {k: self._to_json_compatible(v) for k, v in value.items()}
    elif isinstance(value, (list, tuple)):
        return [self._to_json_compatible(v) for v in value]
    elif isinstance(value, set):
        try:
            return sorted(self._to_json_compatible(v) for v in value)
        except TypeError:
            return [self._to_json_compatible(v) for v in value]
    else:
        raise CodeInterpreterError(f"Unsupported value type: {type(value).__name__}")

def _inject_variables(self, code: str, variables: dict[str, Any]) -> str:
    """Insert Python assignments for each variable at the top of the code."""

